package main

import (
	"bytes"
	"errors"
	"fmt"
	"io"
)

type MyError struct{ Code int }

func (e *MyError) Error() string { return fmt.Sprintf("code=%d", e.Code) }

// 反例：返回类型是 error，内部用具体指针变量，e 为 nil 时 itab 仍非零。
func badDo(ok bool) error {
	var e *MyError
	if !ok {
		e = &MyError{Code: 500}
	}
	return e // e==nil 但 itab(error, *MyError) 已写入，外层 err!=nil 恒成立
}

// 正例：提前判空回 nil，或直接返回字面量。
func goodDo(ok bool) error {
	if ok {
		return nil
	}
	return &MyError{Code: 500}
}

// 值接收者方法：T 和 *T 都实现。
type Val struct{ V int }

func (v Val) String() string { return fmt.Sprintf("val=%d", v.V) }

// 指针接收者方法：只有 *Ptr 实现。
type Ptr struct{ V int }

func (p *Ptr) String() string { return fmt.Sprintf("ptr=%d", p.V) }

func main() {
	// 1) typed nil：buf 是 nil 指针，但 r 的 itab 已被写入。
	var buf *bytes.Buffer
	var r io.Reader = buf
	fmt.Println("r == nil:", r == nil)     // false
	fmt.Println("buf == nil:", buf == nil) // true

	// 2) badDo vs goodDo
	fmt.Println("badDo:", badDo(true) == nil)   // false（陷阱）
	fmt.Println("goodDo:", goodDo(true) == nil)  // true

	// 3) 方法集合：值接收者 → T 和 *T 都行；指针接收者 → 只有 *T。
	var sv Val
	var sp *Val
	var pv Ptr
	var pp *Ptr
	fmt.Println("Val value ok:", fmt.Stringer(sv) != nil)  // 编译通过
	fmt.Println("*Val ok:", fmt.Stringer(sp) != nil)       // 编译通过
	// fmt.Stringer(pv) // 编译错误：Ptr does not implement fmt.Stringer (method String has pointer receiver)
	fmt.Println("*Ptr ok:", fmt.Stringer(pp) != nil)       // 编译通过
	_ = pv // suppress unused

	// 4) comma-ok 断言 + errors.As
	var err error = &MyError{Code: 404}
	if me, ok := err.(*MyError); ok {
		fmt.Println("asserted code:", me.Code)
	}
	var target *MyError
	if errors.As(err, &target) {
		fmt.Println("errors.As code:", target.Code)
	}

	// 5) 接口值比较：动态类型相同且值相等才 true。
	var a any = 42
	var b any = 42
	fmt.Println("a == b:", a == b) // true

	// 6) 不可比较类型做接口比较会 panic（注释掉以保护程序）。
	// var s1 any = []int{1, 2}
	// var s2 any = []int{1, 2}
	// fmt.Println(s1 == s2) // panic: comparing uncomparable type []int
}
